def validate_queue_capacities(document, link_ids):
    """Validate the queue_capacities field; every problem is a ConfigError.

    The object must list every declared link id exactly once with a
    JSON integer value in 0..1000000000000 bytes (booleans are not
    integers). Keys are checked in Unicode code point order so the
    first reported problem is deterministic. Returns a mapping of link
    id to capacity containing one entry per declared link.
    """
    capacities = document["queue_capacities"]
    if not isinstance(capacities, dict):
        raise ConfigError("queue_capacities must be an object")

    declared = set(link_ids)
    listed = set()
    resolved = {}
    for link_id in sorted(capacities):
        if not isinstance(link_id, str):
            raise ConfigError("queue_capacities keys must be strings")
        if link_id not in declared:
            raise ConfigError(
                "queue_capacities refers to an undeclared link: %s" % link_id
            )
        listed.add(link_id)
        value = capacities[link_id]
        if type(value) is not int or not 0 <= value <= MAX_QUEUE_BYTES:
            raise ConfigError(
                "queue_capacities[%s] must be an integer in 0..%d"
                % (link_id, MAX_QUEUE_BYTES)
            )
        resolved[link_id] = value
    missing = declared - listed
    if missing:
        raise ConfigError(
            "queue_capacities is missing declared link: %s"
            % sorted(missing)[0]
        )
    return resolved


